Q = ['q0','q1','q2','q3']
eps = {'q0':['q1'],'q1':[],'q2':['q3'],'q3':[]}
delta = {('q0','a'):['q0'],('q1','b'):['q2'],('q3','a'):['q3']}
F = {'q3'}

def eclose(S):
    out = set(S)
    stack = list(S)
    while stack:
        p = stack.pop()
        for r in eps[p]:
            if r not in out:
                out.add(r)
                stack.append(r)
    return out

def step(S, a):
    nxt = set()
    for p in S:
        for r in delta.get((p, a), []):
            nxt.add(r)
    return eclose(nxt)

def dhat(w):
    S = eclose({'q0'})
    for a in w:
        S = step(S, a)
    return S

print(len(eclose({'q0'})))
print(len(eclose({'q1'})))
print(len(eclose({'q2'})))
print(len(eclose({'q3'})))
print(len([q for q in Q if eclose({q}) & F]))
